const original = ($('On called').first() && $('On called').first().json) || {};
const catResult = ($('Get Categories').first() && $('Get Categories').first().json) || {};
const categories = catResult.categories || [];
const salaryResult = ($input.first() && $input.first().json) || {};

// BudgetFlow's CategoryType enum (INCOME/FIXED_EXPENSE/VARIABLE_EXPENSE/SAVINGS/DEBT/REMITTANCE)
// does not match TransactionType (INCOME/EXPENSE/SAVINGS/DEBT_PAYMENT/TRANSFER/REMITTANCE) 1:1.
const TYPE_MAP = {
  INCOME: ["INCOME"],
  EXPENSE: ["VARIABLE_EXPENSE", "FIXED_EXPENSE"],
  SAVINGS: ["SAVINGS"],
  DEBT_PAYMENT: ["DEBT"],
  REMITTANCE: ["REMITTANCE"],
  TRANSFER: ["VARIABLE_EXPENSE", "FIXED_EXPENSE"],
};
const wantTypes = TYPE_MAP[original.type] || ["VARIABLE_EXPENSE", "FIXED_EXPENSE"];
const eligible = categories.filter((c) => wantTypes.includes(c.type));

// EDIT ME: tune the threshold or the target category name here.
const BIG_EXPENSE_RATIO = 0.20;
const BIG_EXPENSE_CATEGORY_NAME = "rent cash";

let categoryId = null;
let categoryName = null;
let rule = null;

// Rule 1: large expense relative to last known salary -> designated big-expense category.
if (original.type === "EXPENSE" && salaryResult && salaryResult.ok && Array.isArray(salaryResult.items) && salaryResult.items.length > 0) {
  const salaryAmount = parseFloat(salaryResult.items[0].amount);
  const txAmount = parseFloat(original.amount);
  if (salaryAmount > 0 && txAmount > 0 && txAmount / salaryAmount >= BIG_EXPENSE_RATIO) {
    const bigExpenseCategory = categories.find((c) => c.name.toLowerCase() === BIG_EXPENSE_CATEGORY_NAME);
    if (bigExpenseCategory) {
      categoryId = bigExpenseCategory.id;
      categoryName = bigExpenseCategory.name;
      rule = "salary_ratio";
    }
  }
}

// Rule 2: exactly one category matches this transaction's type -> unambiguous, not a guess.
if (!categoryId && eligible.length === 1) {
  categoryId = eligible[0].id;
  categoryName = eligible[0].name;
  rule = "single_type_match";
}

// Rule 3: ordinary expense, no strong signal -> honest Uncategorized fallback.
if (!categoryId && original.type === "EXPENSE") {
  const uncategorized = categories.find((c) => wantTypes.includes(c.type) && c.name.toLowerCase() === "uncategorized");
  if (uncategorized) {
    categoryId = uncategorized.id;
    categoryName = uncategorized.name;
    rule = "uncategorized_fallback";
  }
}

return [{
  json: {
    ...original,
    categoryId,
    categoryName,
    categorizeRule: rule,
  },
}];
